<div class="wp-block-wdl-paid-block-fv-11 swiper paid-block-fv-11 max-w init-hide min-h-pc-440px min-h-tb-380px min-h-sp-300px" style="max-width:100vw"><div class="text_in center"><div class="in"><h1 class="ttl"><span class="sub">FAQ</span>  <span class="main">よくあるご質問</span></h1><p class="description">知りたいことを、上のボタンから選んでください。</p></div></div><div class="swiper-wrapper"><div class="swiper-slide"><picture class="bg_img"><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_01.webp" media="(max-width:800px)"/><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_01.webp" media="(min-width:801px)"/><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_01.webp" alt="診療室"/></picture></div><div class="swiper-slide"><picture class="bg_img"><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_02.webp" media="(max-width:800px)"/><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_02.webp" media="(min-width:801px)"/><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_02.webp" alt="受付"/></picture></div><div class="swiper-slide"><picture class="bg_img"><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_03.webp" media="(max-width:800px)"/><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_03.webp" media="(min-width:801px)"/><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/clinic_staff_03.webp" alt="待合室"/></picture></div><div class="image_filter" style="background-color:#0a2d36;opacity:0.55"></div></div><div class="swiper-pagination"></div><script type="text/javascript">
(function(){
var _sc = document.currentScript;
var _root = ( _sc && _sc.closest ) ? _sc.closest(".paid-block-fv-11") : null;
if ( !_root ) _root = document.querySelector(".paid-block-fv-11:not([data-lw-init])");
if ( !_root ) return;
_root.setAttribute("data-lw-init","1");
if ( !_root.id ) _root.id = "paid-block-fv-11-" + Math.random().toString(36).slice(2,10);
const selector = "#" + _root.id;
const MAX_RETRY = 30; // 30 × 150ms = 4.5s
let retry = 0;

const initSwiper = () => {
    if ( typeof Swiper === "undefined" ) return false;
    const already = document.querySelector(selector).swiper;
    if ( already ) return true; // 二重初期化しない

    const config = {
        loop: true,
        effect: "fade",
        speed: 1000,
        autoplay: {
            delay: 5000,
            disableOnInteraction: false
        },
        observer: true,
        observeParents: true,
        fadeEffect: { crossFade: true },
        
            pagination: {
                el: selector + " .swiper-pagination",
                clickable: true
            },
        
    };
    new Swiper( selector, config );
    document.querySelector(selector).classList.remove("init-hide");
    return true;
};

/* ① DOMContentLoaded 直後 */
document.addEventListener("DOMContentLoaded", initSwiper, { once:true });

/* ② lw:swiperReady (既存仕組み維持) */
window.addEventListener("lw:swiperReady", initSwiper, { once:true });

/* ③ ポーリング（Swiper読み込み遅延対策） */
const timer = setInterval(() => {
    if ( initSwiper() || ++retry >= MAX_RETRY ) clearInterval(timer);
}, 150);

/* ④ それでも失敗したら 5s で init-hide を解除し static 画像表示 */
setTimeout(() => {
    const el = document.querySelector(selector);
    if ( el ) el.classList.remove("init-hide");
}, 5000);
})();
    </script><style>
                    .paid-block-fv-11 .swiper-pagination-bullet { background-color:#ffffff; }
                    .paid-block-fv-11 .swiper-button-next,
                    .paid-block-fv-11 .swiper-button-prev { color:#ffffff; }
                </style><noscript><style>.paid-block-fv-11{opacity:1!important}</style></noscript></div>
