<!-- wp:wdl/lw-pr-qa-4 {"maxWidth":1040,"tabStyle":"pill","tabAlign":"center","showCount":true,"mainColor":"#1f7a8c","tabBg":"#eff6f8","tabTextColor":"#2b3440","activeTextColor":"#ffffff","lineColor":"#d7e4e8","qLabelColor":"#1f7a8c","aLabelColor":"#586570","groups":[{"label":"はじめて","items":[{"text_q":"予約は必要ですか","text_a":"当日でもお受けしますが、待ち時間が読めません。お電話かウェブでご予約いただくと、ほぼお待たせせずにご案内できます。"},{"text_q":"何を持っていけば","text_a":"保険証をお持ちください。お薬を飲んでいる方はお薬手帳も。紹介状がある場合はあわせてお出しください。"},{"text_q":"初診はどのくらい","text_a":"30〜40分ほどです。お話をうかがって、レントゲンを撮り、その日にできる処置までを行います。"},{"text_q":"すぐ治療しますか","text_a":"痛みがある場合はその日に処置します。痛みが無い場合は、検査とご説明だけで終えることもあります。"},{"text_q":"何も分からなくても","text_a":"大丈夫です。「どこが痛いか分からない」というご相談も多いです。一緒に探すところから始めます。"}]},{"label":"痛み・こわさ","items":[{"text_q":"痛いのが苦手です","text_a":"麻酔の前に表面の麻酔をします。針も細いものを使います。それでも不安な方は、最初にお申し出ください。"},{"text_q":"麻酔は効きますか","text_a":"効きにくい体質の方もいらっしゃいます。途中で痛みを感じたら、手を挙げていただければすぐ止めます。"},{"text_q":"途中でやめられる","text_a":"やめられます。「今日はここまで」で構いません。無理に進めることはありません。"},{"text_q":"音が苦手です","text_a":"ヘッドホンをお貸ししています。音楽をお持ちいただいても構いません。"},{"text_q":"何年も来ていない","text_a":"いちばん多いご相談です。責めることはありません。今日できることからお話しします。"}]},{"label":"費用","items":[{"text_q":"保険は使えますか","text_a":"多くの処置は保険が使えます。使えないもの（自費）は、始める前に必ず金額をお伝えします。"},{"text_q":"だいたいいくら","text_a":"初診で保険を使った場合、3割負担で3,000〜5,000円ほどのことが多いです。処置の内容で変わります。"},{"text_q":"カードは使えますか","text_a":"各種クレジットカードと電子マネーがお使いいただけます。自費の処置は分割もご相談ください。"},{"text_q":"見積もりは出ますか","text_a":"自費の処置は、書面でお出しします。持ち帰ってご検討いただいて構いません。"}]},{"label":"お子さま","items":[{"text_q":"何歳から診ますか","text_a":"歯が生えはじめたらいつでも。1歳半健診でご相談を受けることも多いです。"},{"text_q":"泣いてしまいます","text_a":"泣いても構いません。初日は椅子に座るだけで終わることもあります。少しずつ慣れていただきます。"},{"text_q":"親も入れますか","text_a":"お入りください。小さなお子さまは、保護者の方に抱っこしていただいたままで診ることもあります。"},{"text_q":"ベビーカーは","text_a":"そのまま診療室までお入りいただけます。入口に段差はありません。"}]},{"label":"通院・その他","items":[{"text_q":"何回で終わりますか","text_a":"内容によります。初日に「だいたい何回か」の見通しをお伝えします。"},{"text_q":"途中で行けなくなった","text_a":"いつでも再開できます。前回の記録は残っていますので、続きから始めます。"},{"text_q":"駐車場はありますか","text_a":"建物の裏に5台ぶんございます。満車のときは、近くのコインパーキング代を負担しています。"},{"text_q":"歯科医師は選べますか","text_a":"ご希望をおっしゃっていただければ、できるかぎり合わせます。担当が決まったあとの変更も承ります。"}]}]} -->
<div class="wp-block-wdl-lw-pr-qa-4 lw-pr-qa-4 qa-4--pill qa-4--align-center" style="--qa4-max-w:1040px;--qa4-gap:24px;--qa4-label-w:34px;--qa4-main:#1f7a8c;--qa4-tab-bg:#eff6f8;--qa4-tab-color:#2b3440;--qa4-tab-active-color:#ffffff;--qa4-q-color:#1f7a8c;--qa4-a-color:#586570;--qa4-line:#d7e4e8;--qa4-label-size-pc:18px;--qa4-label-size-sp:16px;--qa4-q-size-pc:17px;--qa4-q-size-sp:15px;--qa4-a-size-pc:15px;--qa4-a-size-sp:14px"><div class="qa-4__tabs" role="tablist"><button type="button" class="qa-4__tab is-active" role="tab" aria-selected="true" data-qa4-tab="0"><span class="qa-4__tab-label">はじめて</span><span class="qa-4__tab-count">5</span></button><button type="button" class="qa-4__tab" role="tab" aria-selected="false" data-qa4-tab="1"><span class="qa-4__tab-label">痛み・こわさ</span><span class="qa-4__tab-count">5</span></button><button type="button" class="qa-4__tab" role="tab" aria-selected="false" data-qa4-tab="2"><span class="qa-4__tab-label">費用</span><span class="qa-4__tab-count">4</span></button><button type="button" class="qa-4__tab" role="tab" aria-selected="false" data-qa4-tab="3"><span class="qa-4__tab-label">お子さま</span><span class="qa-4__tab-count">4</span></button><button type="button" class="qa-4__tab" role="tab" aria-selected="false" data-qa4-tab="4"><span class="qa-4__tab-label">通院・その他</span><span class="qa-4__tab-count">4</span></button></div><div class="qa-4__panels"><div class="qa-4__panel is-active" role="tabpanel" data-qa4-panel="0"><p class="qa-4__panel-title">はじめて</p><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">予約は必要ですか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">当日でもお受けしますが、待ち時間が読めません。お電話かウェブでご予約いただくと、ほぼお待たせせずにご案内できます。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">何を持っていけば</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">保険証をお持ちください。お薬を飲んでいる方はお薬手帳も。紹介状がある場合はあわせてお出しください。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">初診はどのくらい</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">30〜40分ほどです。お話をうかがって、レントゲンを撮り、その日にできる処置までを行います。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">すぐ治療しますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">痛みがある場合はその日に処置します。痛みが無い場合は、検査とご説明だけで終えることもあります。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">何も分からなくても</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">大丈夫です。「どこが痛いか分からない」というご相談も多いです。一緒に探すところから始めます。</p></dd></dl></div><div class="qa-4__panel" role="tabpanel" data-qa4-panel="1"><p class="qa-4__panel-title">痛み・こわさ</p><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">痛いのが苦手です</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">麻酔の前に表面の麻酔をします。針も細いものを使います。それでも不安な方は、最初にお申し出ください。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">麻酔は効きますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">効きにくい体質の方もいらっしゃいます。途中で痛みを感じたら、手を挙げていただければすぐ止めます。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">途中でやめられる</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">やめられます。「今日はここまで」で構いません。無理に進めることはありません。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">音が苦手です</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">ヘッドホンをお貸ししています。音楽をお持ちいただいても構いません。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">何年も来ていない</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">いちばん多いご相談です。責めることはありません。今日できることからお話しします。</p></dd></dl></div><div class="qa-4__panel" role="tabpanel" data-qa4-panel="2"><p class="qa-4__panel-title">費用</p><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">保険は使えますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">多くの処置は保険が使えます。使えないもの（自費）は、始める前に必ず金額をお伝えします。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">だいたいいくら</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">初診で保険を使った場合、3割負担で3,000〜5,000円ほどのことが多いです。処置の内容で変わります。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">カードは使えますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">各種クレジットカードと電子マネーがお使いいただけます。自費の処置は分割もご相談ください。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">見積もりは出ますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">自費の処置は、書面でお出しします。持ち帰ってご検討いただいて構いません。</p></dd></dl></div><div class="qa-4__panel" role="tabpanel" data-qa4-panel="3"><p class="qa-4__panel-title">お子さま</p><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">何歳から診ますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">歯が生えはじめたらいつでも。1歳半健診でご相談を受けることも多いです。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">泣いてしまいます</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">泣いても構いません。初日は椅子に座るだけで終わることもあります。少しずつ慣れていただきます。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">親も入れますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">お入りください。小さなお子さまは、保護者の方に抱っこしていただいたままで診ることもあります。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">ベビーカーは</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">そのまま診療室までお入りいただけます。入口に段差はありません。</p></dd></dl></div><div class="qa-4__panel" role="tabpanel" data-qa4-panel="4"><p class="qa-4__panel-title">通院・その他</p><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">何回で終わりますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">内容によります。初日に「だいたい何回か」の見通しをお伝えします。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">途中で行けなくなった</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">いつでも再開できます。前回の記録は残っていますので、続きから始めます。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">駐車場はありますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">建物の裏に5台ぶんございます。満車のときは、近くのコインパーキング代を負担しています。</p></dd></dl><dl class="qa-4__item"><dt><span class="qa-4__mark qa-4__mark--q" data-lw_font_set="Roboto">Q</span><p class="qa-4__q">歯科医師は選べますか</p></dt><dd><span class="qa-4__mark qa-4__mark--a" data-lw_font_set="Roboto">A</span><p class="qa-4__a">ご希望をおっしゃっていただければ、できるかぎり合わせます。担当が決まったあとの変更も承ります。</p></dd></dl></div></div></div>
<!-- /wp:wdl/lw-pr-qa-4 -->
